/**
 * Tiny JPEG fixtures for the PDF compression tests, generated with Pillow.
 * Kept as base64 so the tests need no binary files or image libraries.
 */
const decode = (b64: string) => Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));

/** 40×30 RGB JPEG, quality 95 (noise, so it compresses poorly). */
export const JPEG_BIG = decode(
  "",
);

/** 20×15 RGB JPEG, quality 30 — stands in for a recoded image. */
export const JPEG_SMALL = decode(
  "",
);

/** 40×30 four-component (CMYK) JPEG. */
export const JPEG_CMYK = decode(
  "",
);

/** 40×30 single-component (greyscale) JPEG. */
export const JPEG_GRAY = decode(
  "",
);
